script:
// Shipped by work_management. A record whose approved figures have
// moved says so at the top of its own form -- the same sentence the
// web screens show, fetched from the server rather than recomputed
// here, because two implementations of one question disagree the
// first time either moves.
frappe.ui.form.on('Work Management Master Plan', {
	refresh: function (frm) {
		if (frm.is_new()) return;
		frappe.call({
			method: 'work_management.audit.amended_summary',
			args: { doctype: frm.doc.doctype, name: frm.doc.name },
			callback: function (r) {
				if (r && r.message) frm.set_intro(r.message, 'orange');
			},
		});
	},
});

